'use strict';
const D = window.RETAIL_DATA;
const content = document.querySelector('#content');
if (!D) {
  content.innerHTML = '<div class="notice" role="alert">The analysis data could not load. Refresh the page or rebuild it with scripts/build_data.py.</div>';
} else {
  const countries = [...new Set(D.invoices.map(r => r[0]))].sort();
  const months = [...new Set(D.invoices.map(r => r[1]))].sort();
  const state = {page:'overview',country:'All countries',from:months[0],to:months.at(-1),customerCountry:'All countries',productCountry:'All countries',productFrom:months[0],productTo:months.at(-1),query:'',sort:'sales',productPage:0};
  const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const number = n => new Intl.NumberFormat('en-GB').format(Math.round(n));
  const money = p => new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(p/100);
  const moneyExact = p => new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(p/100);
  const pct = n => new Intl.NumberFormat('en-GB',{style:'percent',maximumFractionDigits:1}).format(n || 0);
  const monthLabel = m => new Date(m+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'short',year:'2-digit',timeZone:'UTC'});
  const options = (values, selected, format = x => x) => values.map(v => `<option value="${esc(v)}" ${v === selected?'selected':''}>${esc(format(v))}</option>`).join('');
  const select = (id,label,values,value,format) => `<label class="field" for="${id}"><span>${label}</span><select id="${id}">${options(values,value,format)}</select></label>`;
  const metric = (label,value,caption,icon='↗') => `<article class="metric"><div class="metric-label">${label}<span class="mini-icon" aria-hidden="true">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-caption">${caption}</div></article>`;
  const panelHeader = (title,sub,extra='') => `<div class="panel-header"><div><h2>${title}</h2><p>${sub}</p></div>${extra}</div>`;
  const notice = text => `<div class="notice">${text}</div>`;
  const sum = (rows,index) => rows.reduce((a,r) => a+r[index],0);
  function selectedInvoices(){return D.invoices.filter(r => (state.country==='All countries'||r[0]===state.country)&&r[1]>=state.from&&r[1]<=state.to);}
  function customerCounts(rows){const customers=new Map();for(const r of rows)if(r[4])customers.set(r[4],(customers.get(r[4])||0)+1);return {count:customers.size,repeat:[...customers.values()].filter(n=>n>1).length};}
  const productNames = new Map(D.products.map(p=>[p.sku,p.name]));
  function productRows(country,from=months[0],to=months.at(-1)){
    const rows=new Map();
    for(const [market,month,sku,sales,units,orders] of D.productMonths){
      if((country!=='All countries'&&market!==country)||month<from||month>to)continue;
      let row=rows.get(sku);if(!row){row={sku,name:productNames.get(sku)||sku,sales:0,units:0,orders:0};rows.set(sku,row);}
      row.sales+=sales;row.units+=units;row.orders+=orders;
    }return [...rows.values()];
  }
  function topProductTable(rows,limit=5){return `<div class="table-scroll"><table><caption class="muted" style="text-align:left;font-size:10px;margin-bottom:10px">${monthLabel(state.from)} – ${monthLabel(state.to)} · ${esc(state.country)}</caption><thead><tr><th>PRODUCT</th><th class="num">UNITS SOLD</th><th class="num">SALES</th><th>TYPE</th></tr></thead><tbody>${rows.sort((a,b)=>b.sales-a.sales).slice(0,limit).map(p=>`<tr><td class="title-cell">${esc(p.name)}<span class="sku">${esc(p.sku)}</span></td><td class="num">${number(p.units)}</td><td class="num">${money(p.sales)}</td><td><span class="pill">Merchandise</span></td></tr>`).join('')}</tbody></table></div>`;}
  function salesChart(rows){
    const values=months.filter(m=>m>=state.from&&m<=state.to).map(m=>({month:m,sales:sum(rows.filter(r=>r[1]===m),2)}));
    const W=680,H=257,L=54,R=10,T=16,B=38,max=Math.max(...values.map(v=>v.sales),1),step=(W-L-R)/values.length;
    let svg=`<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-labelledby="sales-title sales-desc"><title id="sales-title">Monthly merchandise sales</title><desc id="sales-desc">${esc(values.map(v=>monthLabel(v.month)+': '+moneyExact(v.sales)+(v.month===D.meta.partial_month?' (partial month)':'')).join('; '))}</desc>`;
    for(let i=0;i<=4;i++){const y=T+(H-T-B)*i/4,v=max*(1-i/4);svg+=`<line x1="${L}" x2="${W-R}" y1="${y}" y2="${y}" stroke="#eaf0e3" stroke-dasharray="3 4"/><text x="${L-9}" y="${y+4}" text-anchor="end">£${v/100>=1e6?(v/1e8).toFixed(1)+'m':v/100>=1e3?Math.round(v/1e5)+'k':Math.round(v/100)}</text>`;}
    values.forEach((v,i)=>{const h=v.sales/max*(H-T-B),width=Math.min(step*.56,44),x=L+step*i+(step-width)/2,y=H-B-h;svg+=`<rect class="bar ${i===values.length-1?'last':''} ${v.month===D.meta.partial_month?'partial':''}" x="${x}" y="${y}" width="${width}" height="${h}" rx="4"><title>${esc(monthLabel(v.month))}: ${moneyExact(v.sales)}${v.month===D.meta.partial_month?' — partial month':''}</title></rect>`;if(values.length<9||i%2===0||i===values.length-1)svg+=`<text x="${L+step*(i+.5)}" y="${H-13}" text-anchor="middle">${esc(monthLabel(v.month))}</text>`;});
    return svg+'</svg>'+`<details><summary>View chart data as a table</summary><table><thead><tr><th>Month</th><th class="num">Sales</th></tr></thead><tbody>${values.map(v=>`<tr><td>${monthLabel(v.month)}${v.month===D.meta.partial_month?' (partial)':''}</td><td class="num">${moneyExact(v.sales)}</td></tr>`).join('')}</tbody></table></details>`;
  }
  function overview(){
    const rows=selectedInvoices(),sales=sum(rows,2),cc=customerCounts(rows),knownSales=sum(rows.filter(r=>r[4]),2);
    const byCountry=new Map();for(const r of rows)byCountry.set(r[0],(byCountry.get(r[0])||0)+r[2]);const ranked=[...byCountry].sort((a,b)=>b[1]-a[1]);
    const best=ranked[0], share=best?best[1]/sales:0;
    return `<div class="filters"><div class="filter-group">${select('country','Market', ['All countries',...countries],state.country)}${select('from','From',months,state.from,monthLabel)}${select('to','To',months,state.to,monthLabel)}</div><span class="filter-note">All overview panels follow these filters</span></div>
    <div class="period-strip"><span>${months.filter(m=>m>=state.from&&m<=state.to).length} observed months · ${esc(state.country)} ${state.to===D.meta.partial_month?'<span class="partial-tag">Includes partial December</span>':''}</span><div><button class="text-button" id="complete-months">Complete months</button><button class="text-button" id="reset-filters">Reset filters ↺</button></div></div>
    <div class="metrics">${metric('Merchandise sales',money(sales),'Positive merchandise lines · <strong>GBP</strong>','£')}${metric('Orders',number(rows.length),'Distinct retained purchase invoices','▤')}${metric('Purchasing customers',number(cc.count),'Known IDs only · '+pct(sales?knownSales/sales:0)+' of selected sales','◎')}${metric('Average order value',money(rows.length?sales/rows.length:0),'Selected sales ÷ selected orders','↗')}</div>
    <div class="grid-main"><section class="panel">${panelHeader('Sales over time','The rhythm behind the numbers.','<span class="legend">Merchandise sales</span>')}${rows.length?salesChart(rows):'<div class="empty">No purchases in this selection. Try a wider date range.</div>'}<p class="chart-tip">${state.to===D.meta.partial_month?'December 2011 contains only December 1–9. Its outlined bar represents a partial month.':'Bars represent calendar months within the observed dataset.'}</p></section><section class="panel">${panelHeader('Where sales come from','Sales by customer country.','<span class="tag">TOP 5 MARKETS</span>')}${ranked.slice(0,5).map(([country,value],i)=>`<div class="country-item"><div class="row-between"><span class="country-name"><span class="country-rank">${String(i+1).padStart(2,'0')}</span>${esc(country)}</span><span class="country-money">${money(value)}</span></div><div class="track"><span style="width:${value/sales*100}%"></span></div></div>`).join('')||'<div class="empty">No market data.</div>'}<div class="country-foot">${best?`${esc(best[0])} accounts for <strong>${pct(share)}</strong> of sales in this selection.`:'Change the filters to explore a market.'}</div></section></div>
    <aside class="insight-banner"><span class="insight-icon" aria-hidden="true">✧</span><div><h3>Repeat purchases are a useful place to look.</h3><p>${cc.count?`${pct(cc.repeat/cc.count)} of identified customers in this selection placed more than one order. Explore purchase patterns and descriptive customer segments.`:'No identified customers in this selection. Customer metrics exclude transactions without an ID.'}</p></div><a href="#customers">Explore customers ↗</a></aside>
    <section class="panel">${panelHeader('The products driving sales','A closer look at the strongest sellers.','<a class="subtle-link" href="#products">Explore products ↗</a>')}${topProductTable(productRows(state.country,state.from,state.to))}<div class="table-bottom"><span>All values on this page follow the selected market and date range. Sales exclude returns and cancellations.</span></div></section>`;
  }
  const segmentCopy={
    'Champions':['Recent, frequent, high-spend buyers.','Test early access or a loyalty reward.'],
    'Loyal':['Frequent buyers active within 90 days.','Test relevant cross-sell recommendations.'],
    'New & promising':['Recent buyers outside the frequent-buyer rules.','Test a helpful second-purchase reminder.'],
    'Needs attention':['Last purchase was 31–90 days ago; fewer than 3 orders.','Test a tailored product discovery email.'],
    'At risk':['Frequent buyers with no purchase for over 90 days.','Test a win-back campaign with a holdout.'],
    'Hibernating':['Over 90 days since purchase; fewer than 3 orders.','Test low-cost reactivation before paid incentives.']
  };
  function customerSegments(){const filtered=D.segments.filter(s=>state.customerCountry==='All countries'||s.country===state.customerCountry);return Object.keys(segmentCopy).map(name=>{const rows=filtered.filter(s=>s.segment===name);return {segment:name,customers:rows.reduce((a,s)=>a+s.customers,0),sales:rows.reduce((a,s)=>a+s.sales,0)};});}
  function customers(){const segs=customerSegments(),total=segs.reduce((a,s)=>a+s.customers,0),cohortRows=state.customerCountry==='All countries'?D.cohorts:(D.cohortMarkets[state.customerCountry]||[]);return `<div class="filters"><div class="filter-group">${select('customer-country','Customer market',['All countries',...countries],state.customerCountry)}</div><span class="filter-note">Full-period snapshot as of ${D.meta.reference}</span></div>${notice('These are descriptive purchase segments, not churn predictions. A customer’s country is assigned from their last observed purchase. The high-spend threshold is fixed across markets.')}
    <div class="segment-grid">${segs.map(s=>`<article class="segment"><h3>${esc(s.segment)}</h3><span class="segment-value">${number(s.customers)}</span><span class="segment-share">${pct(total?s.customers/total:0)} of customers</span><p>${segmentCopy[s.segment][0]}<br><strong>${money(s.sales)}</strong> in observed merchandise sales.</p><p class="action">${segmentCopy[s.segment][1]}</p></article>`).join('')}</div>
    <section class="panel section-space">${panelHeader('Do customers come back?','Monthly repeat activity by first observed purchase month.','<span class="tag">${esc(state.customerCountry.toUpperCase())} · COMPLETE MONTHS</span>')}<p>Each row follows a group of customers. Month 0 is their first observed purchase; subsequent cells show the share buying again in that month. The selected market applies to segments and cohorts, using the country of each customer’s last observed purchase.</p><div class="table-scroll"><table class="cohort"><thead><tr><th>FIRST PURCHASE</th><th>BUYERS</th>${Array.from({length:12},(_,i)=>`<th>M${i}</th>`).join('')}</tr></thead><tbody>${cohortRows.map(c=>`<tr><th scope="row">${monthLabel(c.month)}</th><td>${number(c.size)}</td>${Array.from({length:12},(_,i)=>i<c.rates.length?`<td class="heat" style="background:rgba(109,157,80,${.08+c.rates[i]*.75})" title="${monthLabel(c.month)}, month ${i}: ${pct(c.rates[i])}">${pct(c.rates[i])}</td>`:'<td class="na" title="Not yet observable in complete months">—</td>').join('')}</tr>`).join('')}</tbody></table></div><div class="table-bottom"><span>December 2011 is excluded because it is incomplete. Blank cells are unobserved, not zero retention.</span><a class="subtle-link" href="#methodology">Read the definitions ↗</a></div></section>
    <aside class="insight-banner"><span class="insight-icon" aria-hidden="true">◎</span><div><h3>A segment is a starting hypothesis.</h3><p>Compare campaign response against a randomized holdout before claiming that a retention action creates value. No campaign uplift or customer lifetime value is estimated here.</p></div></aside>`;}
  function filteredProducts(){return productRows(state.productCountry,state.productFrom,state.productTo).filter(p=>(p.name+' '+p.sku).toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>b[state.sort]-a[state.sort]||a.sku.localeCompare(b.sku));}
  function products(){const rows=filteredProducts(),size=15,pages=Math.max(1,Math.ceil(rows.length/size));state.productPage=Math.min(state.productPage,pages-1);const start=state.productPage*size,all=productRows(state.productCountry,state.productFrom,state.productTo),sales=all.reduce((a,p)=>a+p.sales,0);return `<div class="filters"><div class="filter-group">${select('product-country','Market',['All countries',...countries],state.productCountry)}${select('product-from','From',months,state.productFrom,monthLabel)}${select('product-to','To',months,state.productTo,monthLabel)}<label class="field" for="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Search products or stock codes" aria-label="Search products or stock codes" value="${esc(state.query)}"></label>${select('sort','Sort by',['sales','units','orders'],state.sort,v=>({sales:'Sales',units:'Units sold',orders:'Order appearances'}[v]))}</div><span class="filter-note">Market & dates apply to all product metrics</span></div><div class="metrics">${metric('Merchandise products',number(all.length),'Distinct stock codes in this market','▧')}${metric('Units sold',number(all.reduce((a,p)=>a+p.units,0)),'Positive merchandise quantities','↗')}${metric('Top 10 sales share',pct(sales?all.sort((a,b)=>b.sales-a.sales).slice(0,10).reduce((a,p)=>a+p.sales,0)/sales:0),'Concentration across the ten largest sellers','◉')}${metric('Merchandise sales',money(sales),'Selected period · selected market','£')}</div><section class="panel">${panelHeader('Product explorer','Find the products behind the performance.','<span class="tag">'+number(rows.length)+' MATCHES</span>')}<div class="table-scroll"><table><thead><tr><th>RANK</th><th>PRODUCT / STOCK CODE</th><th class="num">UNITS SOLD</th><th class="num">ORDER APPEARANCES</th><th class="num">SALES</th><th class="num">SALES SHARE</th></tr></thead><tbody>${rows.slice(start,start+size).map((p,i)=>`<tr><td>${String(start+i+1).padStart(2,'0')}</td><td class="title-cell">${esc(p.name)}<span class="sku">${esc(p.sku)}</span></td><td class="num">${number(p.units)}</td><td class="num">${number(p.orders)}</td><td class="num">${moneyExact(p.sales)}</td><td class="num">${pct(sales?p.sales/sales:0)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No matching products. Try another description or stock code.</td></tr>'}</tbody></table></div><div class="table-bottom"><span>Showing ${rows.length?start+1:0}–${Math.min(start+size,rows.length)} of ${number(rows.length)} products. Search affects this table and its export.</span><div class="pager"><button class="button" id="prev" ${state.productPage===0?'disabled':''} aria-label="Previous product page">←</button><span>Page ${state.productPage+1} / ${pages}</span><button class="button" id="next" ${state.productPage===pages-1?'disabled':''} aria-label="Next product page">→</button></div></div></section><div class="notice" style="margin-top:20px">Sales are not profit: this dataset contains no cost, inventory or margin information. Order appearances count invoices containing each product; adding them across products double-counts baskets. Description is the most common observed name for each stock code.</div>`;}
  function methodology(){const q=D.meta;return `<div class="metrics">${metric('Original records',number(q.source_rows),'Full source workbook · no sampling','▤')}${metric('Retained records',number(q.retained_rows),pct(q.retained_rows/q.source_rows)+' retained after documented exclusions','✓')}${metric('Customer coverage',pct(q.identified_sales/q.sales),'Share of sales with a known customer ID','◎')}${metric('Observed markets',number(q.countries),'Distinct country labels in retained purchases','◉')}</div>
    <div class="method-grid"><section class="panel prose">${panelHeader('01 / The business question','Understand performance before choosing an action.')}<p>Which markets and products drive merchandise sales, and what do purchase patterns suggest about customer engagement?</p><p>The project combines a reproducible <strong>Python pipeline</strong>, a local <strong>SQLite database</strong>, documented SQL queries, and this interactive dashboard. It deliberately uses descriptive analytics rather than adding a model without a decision to support.</p><h3>Source & attribution</h3><p>Chen, D. (2015). <a href="https://doi.org/10.24432/C5BW33" target="_blank" rel="noopener">Online Retail, UCI Machine Learning Repository</a>. Licensed under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>. The data has been cleaned and aggregated for this project.</p><p>A UK-based online gift retailer, including wholesale buyers. Observed transactions run from <strong>1 December 2010 to 9 December 2011</strong>. This is a historical case study, not live business reporting.</p><p>The dataset is publicly available. Only aggregated metrics and opaque customer keys used for counting are sent to this dashboard. Original customer IDs stay out of the public payload.</p></section>
    <section class="panel">${panelHeader('02 / The cleaning audit','Sequential exclusions; each removed line is counted once.')}<div class="table-scroll"><table><thead><tr><th>STEP</th><th class="num">LINES</th></tr></thead><tbody>${q.audit.map(a=>`<tr><td>${esc(a.step)}</td><td class="num">${a.excluded!==undefined?'−':''}${number(a.excluded??a.rows)}</td></tr>`).join('')}</tbody></table></div><p style="margin-top:14px">Missing customer IDs are retained in sales totals. ${number(q.missing_customer_rows)} retained lines cannot be used in customer analysis.</p></section>
    <section class="panel prose">${panelHeader('03 / Metric definitions','One definition for every number.')}<ul><li><strong>Merchandise sales:</strong> quantity × unit price, rounded to pence per line, summed after exclusions. Not net revenue; cancellations and returns are excluded.</li><li><strong>Orders:</strong> distinct retained purchase invoices in the selection.</li><li><strong>Average order value:</strong> selected merchandise sales divided by selected orders.</li><li><strong>Purchasing customers:</strong> distinct identified buyers in the selection. Anonymous purchases are not guessed.</li><li><strong>Repeat purchase share:</strong> identified buyers with more than one selected invoice, divided by all identified selected buyers.</li><li><strong>Cohort repeat activity:</strong> buyers active in an observed month divided by buyers in their first observed purchase cohort. First observed purchase is not necessarily true acquisition.</li></ul><p>Currency is GBP throughout. No exchange rates or estimated financial values are used.</p></section>
    <section class="panel prose">${panelHeader('04 / Customer segmentation','Transparent rules, evaluated in the order below.')}<p>Reference date: <strong>${q.reference}</strong>. Recency is days since last observed purchase; frequency is distinct invoices; monetary value is total retained merchandise sales.</p><ol><li><strong>Champions:</strong> recency ≤30 days, frequency ≥3, sales ≥${moneyExact(q.high_value_threshold_pence)} (the global 75th percentile).</li><li><strong>Loyal:</strong> recency ≤90 days and frequency ≥3.</li><li><strong>New & promising:</strong> recency ≤30 days.</li><li><strong>Needs attention:</strong> recency ≤90 days.</li><li><strong>At risk:</strong> frequency ≥3.</li><li><strong>Hibernating:</strong> all remaining identified customers.</li></ol><p>These labels describe history. “New” does not prove acquisition, and “at risk” is not a trained churn prediction.</p></section>
    <section class="panel prose">${panelHeader('05 / Limitations & next experiments','Keep conclusions proportional to the evidence.')}<ul><li>December 2011 is incomplete; no full-month growth rate is shown for it.</li><li>Returns are not matched to purchases. This dashboard does not estimate net sales.</li><li>Postage, manual adjustments, service codes and gift-voucher codes are excluded; no arbitrary high-value outlier cutoff is applied.</li><li>No cost data, marketing exposure, stock history or randomized interventions are available.</li><li>Cohorts are left-censored at the start and right-censored at the end of the dataset.</li></ul><p><strong>Next experiment:</strong> test a retention message for frequent buyers inactive for 90+ days, with a randomized holdout and a prespecified repeat-purchase outcome. This project does not claim campaign results.</p></section>
    <section class="panel prose">${panelHeader('06 / Reproduce & verify','The dashboard is the presentation layer.')}<p>The source project includes <code>scripts/build_data.py</code>, <code>sql/analysis.sql</code>, unit tests, an audit, a data dictionary, and a written case study.</p><p>Build the dataset with <code>python scripts/build_data.py</code>. Run validation with <code>python -m unittest discover -s tests -v</code>. Serve the dashboard with <code>python scripts/serve.py</code>.</p><p>All totals reconcile in integer pence across line items, invoices, products, SQL and the dashboard payload. No generated or placeholder transactions are mixed into the analysis.</p><p><strong>Source archive SHA-256</strong></p><p style="overflow-wrap:anywhere;font-family:monospace;font-size:10px">${esc(q.source_sha256)}</p></section></div>`;}
  const titles={overview:['A clearer view of your business.','From individual transactions to the bigger picture.'],customers:['Understand the people behind the purchases.','Customer segments and repeat activity, grounded in observed behavior.'],products:['Find your next merchandising question.','Explore sales concentration, units and purchase frequency.'],methodology:['Good insights start with honest numbers.','The source, definitions, decisions and limits behind this analysis.']};
  function render(){const focused=document.activeElement?.id;document.querySelectorAll('[data-page]').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('#crumb').textContent=state.page[0].toUpperCase()+state.page.slice(1);document.querySelector('#page-title').textContent=titles[state.page][0];document.querySelector('#page-subtitle').textContent=titles[state.page][1];document.title=state.page[0].toUpperCase()+state.page.slice(1)+' — Retail Intelligence';content.innerHTML=({overview,customers,products,methodology}[state.page])();bind();if(focused)document.getElementById(focused)?.focus({preventScroll:true});document.querySelector('#view-status').textContent=state.page==='overview'?'Overview updated: '+state.country+', '+monthLabel(state.from)+' to '+monthLabel(state.to):'Showing '+state.page;}
  function bind(){const on=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);on('complete-months','click',()=>{state.to=months.at(-2);if(state.from>state.to)state.from=months[0];render();});on('reset-filters','click',()=>{state.country='All countries';state.from=months[0];state.to=months.at(-1);render();});on('product-from','change',e=>{state.productFrom=e.target.value;if(state.productFrom>state.productTo)state.productTo=state.productFrom;state.productPage=0;render();});on('product-to','change',e=>{state.productTo=e.target.value;if(state.productTo<state.productFrom)state.productFrom=state.productTo;state.productPage=0;render();});on('country','change',e=>{state.country=e.target.value;render();});on('from','change',e=>{state.from=e.target.value;if(state.from>state.to)state.to=state.from;render();});on('to','change',e=>{state.to=e.target.value;if(state.to<state.from)state.from=state.to;render();});on('customer-country','change',e=>{state.customerCountry=e.target.value;render();});on('product-country','change',e=>{state.productCountry=e.target.value;state.productPage=0;render();});on('sort','change',e=>{state.sort=e.target.value;state.productPage=0;render();});on('search','input',e=>{state.query=e.target.value;state.productPage=0;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();if(input.type==='search'&&pos!==null)input.setSelectionRange(pos,pos);});on('prev','click',()=>{state.productPage--;render();document.querySelector('#prev')?.focus();});on('next','click',()=>{state.productPage++;render();document.querySelector('#next')?.focus();});}
  function download(name,rows){const safe=value=>{let v=String(value??'');if(/^[=+@\-\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};const csv='\ufeff'+rows.map(row=>row.map(safe).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const toast=document.querySelector('#toast');toast.textContent='Export ready — '+name;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3500);}
  document.querySelector('#export').addEventListener('click',()=>{if(state.page==='products'){download('retail-products.csv',[['stock_code','description','units','order_appearances','sales_gbp','market','from_month','to_month'],...filteredProducts().map(p=>[p.sku,p.name,p.units,p.orders,(p.sales/100).toFixed(2),state.productCountry,state.productFrom,state.productTo])]);}else if(state.page==='customers'){download('retail-segments.csv',[['segment','customers','sales_gbp','market','reference_date'],...customerSegments().map(s=>[s.segment,s.customers,(s.sales/100).toFixed(2),state.customerCountry,D.meta.reference])]);}else if(state.page==='methodology'){download('retail-cleaning-audit.csv',[['step','rows','excluded'],...D.meta.audit.map(a=>[a.step,a.rows??'',a.excluded??''])]);}else{const rows=selectedInvoices();download('retail-monthly-sales.csv',[['month','market','sales_gbp','orders','identified_customers','repeat_customers','partial_month'],...months.filter(m=>m>=state.from&&m<=state.to).map(m=>{const selected=rows.filter(r=>r[1]===m),cc=customerCounts(selected);return[m,state.country,(sum(selected,2)/100).toFixed(2),selected.length,cc.count,cc.repeat,m===D.meta.partial_month];})]);}});
  function route(){const page=location.hash.slice(1);state.page=Object.hasOwn(titles,page)?page:'overview';render();}
  window.addEventListener('hashchange',()=>{if(location.hash==='#main'){document.querySelector('#main').focus();return;}route();window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main').focus({preventScroll:true});});route();
}
